INSERT INTO discuss (id, title, description, cover_image, author, publish_time, view_count, status, create_time) VALUES
                                                                                                                     (1, '2026新赛季规则大改解读', '新的空气动力学规则将会对车队格局产生巨大影响，红牛、法拉利谁能领跑？', '/images/discuss1.png', '赛车爱好者', '2026-04-08', 0, 1, '2026-04-22 16:52:39'),
                                                                                                                     (2, '维斯塔潘本赛季表现分析', '稳定发挥还是状态下滑？一起来聊聊新赛季的塔潘。', '/images/discuss2.png', '车迷前线', '2026-04-07', 0, 1, '2026-04-22 16:52:39'),
                                                                                                                     (3, '中国大奖赛上海赛道观赛指南', '座位选择、交通攻略、现场打卡点全汇总。', '/images/discuss3.png', '赛道老粉', '2026-04-06', 0, 1, '2026-04-22 16:52:39'),
                                                                                                                     (4, '周冠宇新赛季前景展望', '车队资源、队友对比、积分预测，你怎么看？', '/images/discuss4.png', 'F1速报', '2026-04-05', 0, 1, '2026-04-22 16:52:39'),
                                                                                                                     (5, '各车队新车设计对比', '从散热、底板、尾翼角度深度对比2026赛季新车。', '/images/discuss5.png', '技术宅', '2026-04-04', 0, 1, '2026-04-22 16:52:39'),
                                                                                                                     (6, 'test', 'test', NULL, 'test', '2026-04-22', 0, 1, '2026-04-22 18:39:27'),
                                                                                                                     (8, '23', '2323', NULL, '2323', '2026-05-07', 0, 1, '2026-05-07 00:04:21');
INSERT INTO driver (id, name, team, avatar, number, country, description, create_time) VALUES
                                                                                           (4, 'Max Verstappen（马克斯・维斯塔潘）', '红牛车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Max%20Verstappen.jpg', 1, '荷兰', '四届 F1 世界冠军，红牛车队核心车手，以极致的攻防能力和稳定的冠军统治力著称，2026 赛季将冲击个人第五个世界冠军。', '2026-05-09 15:15:29'),
                                                                                           (5, 'Isack Hadjar（伊萨克・哈贾尔）', '红牛车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Isack%20Hadjar.jpg', 6, '法国', '红牛青训体系出身，2025 年 F2 年度冠军，2026 赛季晋升红牛主力，是红牛力捧的下一代核心车手。', '2026-05-09 15:16:00'),
                                                                                           (6, 'Lando Norris（兰多・诺里斯）', '迈凯伦车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Lando%20Norris.jpg', 4, '英国', '迈凯伦车队王牌车手，英国本土车迷的人气担当，以细腻的控车技术和稳定的领奖台表现著称，2026 赛季将冲击世界冠军。', '2026-05-09 15:16:17'),
                                                                                           (7, 'Oscar Piastri（奥斯卡・皮亚斯特里）', '迈凯伦车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Oscar%20Piastri.jpg', 81, '澳大利亚', '前 F2 冠军，迈凯伦重点培养的年轻车手，2023 年升入 F1，以出色的适应能力和雨战表现受到关注。', '2026-05-09 15:16:37'),
                                                                                           (8, 'Charles Leclerc（夏尔・勒克莱尔）', '法拉利车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Charles%20Leclerc.jpg', 16, '摩纳哥', '法拉利车队队长，摩纳哥天才车手，以激进的驾驶风格和杆位竞争力著称，是法拉利复兴的核心希望。', '2026-05-09 15:16:53'),
                                                                                           (9, 'Lewis Hamilton（刘易斯・汉密尔顿）', '法拉利车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Lewis%20Hamilton.jpg', 44, '英国', '七届 F1 世界冠军，2025 年加盟法拉利，将用丰富的经验帮助车队冲击冠军，也是 F1 历史上最成功的车手之一。', '2026-05-09 15:17:12'),
                                                                                           (10, 'George Russell（乔治・拉塞尔）', '梅赛德斯车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/George%20Russell.jpg', 63, '英国', '梅赛德斯车队主力车手，以稳定的发挥和团队协作能力著称，曾在 2022 年巴西站为车队拿下分站冠军。', '2026-05-09 15:17:29'),
                                                                                           (11, 'Kimi Antonelli（基米・安东内利）', '梅赛德斯车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Andrea%20Kimi%20Antonelli.jpg', 12, '意大利', '梅赛德斯青训新星，17 岁时拿下 F2 年度亚军，2026 赛季正式升入 F1，是意大利车迷的未来希望。', '2026-05-09 15:17:44'),
                                                                                           (12, 'Fernando Alonso（费尔南多・阿隆索）', '阿斯顿・马丁车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Fernando%20Alonso.jpg', 14, '西班牙', '两届 F1 世界冠军，44 岁高龄仍保持顶尖竞争力，以丰富的比赛经验和 "冠军之心" 著称，是围场的传奇老将。', '2026-05-09 15:17:59'),
                                                                                           (13, 'Lance Stroll（兰斯・斯特罗尔）', '阿斯顿・马丁车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Lance%20Stroll.jpg', 18, '加拿大', '阿斯顿・马丁车队股东之子，以稳健的驾驶风格和对车队的长期投入著称，曾在 2020 年意大利站登上领奖台。', '2026-05-09 15:18:15'),
                                                                                           (14, 'Pierre Gasly（皮埃尔・加斯利）', 'Alpine 车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Pierre%20Gasly.jpg', 10, '法国', '2020 年意大利站冠军，法国本土车迷的骄傲，以顽强的比赛风格和雨战能力著称，是 Alpine 车队的核心车手。', '2026-05-09 15:19:19'),
                                                                                           (15, 'Carlos Sainz (卡洛斯・塞恩斯)', '威廉姆斯车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Carlos%20Sainz.jpg', 55, '西班牙', '西班牙实力派车手，WRC 世界冠军之子。2015 年出道，曾效力于红牛二队、雷诺、迈凯伦。2021-2024 年效力法拉利，斩获4 次分站冠军（含 2022 英国站首胜）。2025 赛季转会威廉姆斯，与阿尔本搭档。技术全面，轮胎管理与比赛节奏顶尖，风格沉稳冷静，是车队的稳定得分点与经验核心。', '2026-05-09 15:19:32'),
                                                                                           (16, 'Liam Lawson（利亚姆・劳森）', 'Racing Bulls 车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Liam%20Lawson.jpg', 30, '新西兰', '红牛青训车手，2023 年曾顶替加斯利出战 F1，以激进的驾驶风格和新西兰车迷的支持著称。', '2026-05-09 15:19:49'),
                                                                                           (17, 'Arvid Lindblad（阿维德・林德布拉德）', 'Racing Bulls 车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Arvid%20Lindblad.jpg', 41, '英国', '红牛青训体系新星，2025 年 F3 年度冠军，2026 赛季升入 F1，是英国本土备受关注的年轻车手。', '2026-05-09 15:20:07'),
                                                                                           (18, 'Esteban Ocon（埃斯特班・奥康）', '哈斯车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Esteban%20Ocon.jpg', 31, '法国', '2021 年匈牙利站冠军，以精准的防守和团队协作能力著称，2026 赛季加盟哈斯，将带领车队冲击积分。', '2026-05-09 15:20:19'),
                                                                                           (19, 'Oliver Bearman（奥利弗・贝尔曼）', '哈斯车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Oliver%20Bearman.jpg', 87, '英国', '法拉利青训车手，2024 年顶替勒克莱尔出战沙特站，以 18 岁的年龄表现惊艳，2026 赛季正式成为哈斯主力。', '2026-05-09 15:20:33'),
                                                                                           (20, 'Alex Albon（亚历山大・阿尔本）', '威廉姆斯车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Alexander%20Albon.jpg', 23, '泰国', '威廉姆斯车队核心车手，泰国首位登上 F1 领奖台的车手，以雨战表现和顽强的比赛风格著称。', '2026-05-09 15:20:55'),
                                                                                           (21, 'Franco Colapinto（弗兰科・科拉平托）', 'Alpine', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Franco%20Colapinto.jpg', 43, '阿根廷', '阿根廷青训车手，2025 年 F2 年度亚军，2026 赛季升入 F1，是阿根廷车迷的新希望。', '2026-05-09 15:21:09'),
                                                                                           (22, 'Valtteri Bottas（瓦尔特利・博塔斯）', '凯迪拉克车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Valtteri%20Bottas.jpg', 77, '芬兰', '五届分站冠军，梅赛德斯前二号车手，以稳定的排位赛表现和团队协作著称，2026 赛季加盟凯迪拉克，带领新车队起步。', '2026-05-09 15:21:23'),
                                                                                           (23, 'Nico Hülkenberg（尼科・霍肯伯格）', '奥迪车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Nico%20Hulkenberg.jpg', 27, '德国', '围场 "无冕之王"，以从未登上领奖台却始终保持竞争力著称，2026 赛季加盟奥迪车队，将用经验帮助新车队起步。', '2026-05-09 15:22:06'),
                                                                                           (24, 'Gabriel Bortoleto（加布里埃尔・博托莱托）', '奥迪车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Gabriel%20Bortoleto.jpg', 5, '巴西', '2023 年 F3 年度冠军，奥迪青训体系出身，2026 赛季升入 F1，是巴西车迷的新希望。', '2026-05-09 15:23:17'),
                                                                                           (25, 'Sergio Perez（塞尔吉奥・佩雷兹）', '凯迪拉克车队', 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/Sergio%20Perez.jpg', 11, '墨西哥', '六届分站冠军，前红牛车队二号车手，以出色的保胎能力和雨战表现著称，2026 赛季与博塔斯搭档，为凯迪拉克积累宝贵经验。', '2026-05-09 15:27:33');
INSERT INTO team (id, name, full_name, country, founded_year, championships, image, description) VALUES
                                                                                                     (1, '红牛', 'Oracle Red Bull Racing', '奥地利', '2005', 6, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/redbull.jpg', '甲骨文红牛车队由迪特里希·马特希茨于2005年创立，2010年起开启王朝模式。维斯塔潘2021-2024年连续四年夺得车手总冠军，车队同期包揽车队总冠军。2026年纽维离队后面临技术团队重组挑战，但仍是夺冠热门。'),
                                                                                                     (2, '法拉利', 'Scuderia Ferrari', '意大利', '1929', 16, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/ferrari.jpg', '法拉利车队由恩佐·法拉利于1929年创立，是F1唯一从1950年参赛至今的车队。16个车队总冠军、15个车手总冠军的辉煌历史无人能及。2025年汉密尔顿加盟与勒克莱尔组成梦幻阵容，2026年新规下目标终结冠军荒。'),
                                                                                                     (3, '梅赛德斯', 'Mercedes-AMG Petronas F1 Team', '德国', '1954', 8, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/mercedes.jpg', '梅赛德斯AMG车队2010年重返F1，2014-2021年混动时代八连冠建立王朝。汉密尔顿七冠王成就历史第一人。2026年技术规则大改，车队押注全新动力单元概念，拉塞尔与安东内利组成全新阵容。'),
                                                                                                     (4, '迈凯伦', 'McLaren F1 Team', '英国', '1963', 8, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/mclaren.jpg', '迈凯伦车队由布鲁斯·迈凯伦1963年创立，8个车队总冠军、12个车手总冠军。塞纳、汉密尔顿等传奇均出自此处。2024年诺里斯与皮亚斯特里带领车队重返巅峰，2026年新规下有望冲击阔别多年的总冠军。'),
                                                                                                     (5, '阿斯顿马丁', 'Aston Martin Aramco F1 Team', '英国', '2018', 0, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/astonmartin.jpg', '阿斯顿·马丁车队2021年以厂队身份重返F1，劳伦斯·斯托尔重金打造。2023年阿隆索多次登台展现竞争力。2026年与本田合作使用日本厂商动力单元，技术架构全面重组，目标进入争冠集团。'),
                                                                                                     (6, 'Alpine', 'BWT Alpine F1 Team', '法国', '1977', 2, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/alpine.jpg', 'Alpine车队前身雷诺1977年参赛，2005-2006年阿隆索时期两夺双料冠军。2021年更名为Alpine品牌。2026年车队陷入动荡，管理层频繁更迭，但法国厂商仍坚持厂队身份，期待新规翻身。'),
                                                                                                     (7, '威廉姆斯', 'Williams Racing', '英国', '1977', 9, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/williams.jpg', '威廉姆斯车队1977年由弗兰克·威廉姆斯创立，9个车队总冠军、7个车手总冠军。塞纳、曼塞尔等传奇在此成名。2020年被Dorilton Capital收购后艰难重建，2026年塞恩斯与阿尔本组合带来复兴希望。'),
                                                                                                     (8, '哈斯', 'Haas F1 Team', '美国', '2014', 0, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/haas.jpg', '哈斯车队2014年由吉尼·哈斯创立，是F1首支美国籍所有者车队。与法拉利技术合作维持运营。2026年新规下预算帽优势显现，贝尔曼与奥康组成全新阵容，目标稳定拿分。'),
                                                                                                     (9, '竞速公牛', 'Racing Bulls', '意大利', '2006', 0, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/racingbulls.jpg', '竞速公牛车队2026年由小红牛更名而来，仍是红牛二队定位。意大利法恩扎总部承担年轻车手培养任务。哈贾尔与林布拉德组成超新星阵容，车队目标是成为中上游搅局者，为红牛输送人才。'),
                                                                                                     (10, '奥迪', 'Audi F1 Team', '德国', '2026', 0, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/audi.jpg', '奥迪车队2026年正式加入F1，全资收购索伯车队作为参赛平台。德国厂商投入巨资打造动力单元与底盘，霍肯伯格与博尔托莱托组成经验+潜力组合。作为F1新规下首支全新厂队，奥迪被寄予厚望。'),
                                                                                                     (11, '凯迪拉克', 'Cadillac F1 Team', '美国', '2026', 0, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/team/cadillac.jpg', '凯迪拉克车队2026年作为F1第11支车队参赛，通用汽车旗下豪华品牌首次进入顶级方程式。美国车队与Dallara合作底盘，动力单元来源待确认。科拉平托与车手阵容待定，目标是建立美系F1新势力。');
INSERT INTO track (id, name, location, length, lap, image, description, create_time) VALUES
                                                                                         (1, '阿尔伯特公园赛道', '澳大利亚', '5.303km', 58, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Melbourne%20Grand%20Prix%20Circuit.jpg', '坐落于墨尔本阿尔伯特公园内，属于风景优美的公园型赛道，赛道布局经过多次优化，弯角组合流畅，抓地力会随比赛进程逐步提升。墨尔本天气多变，时常出现风云突变的赛事场面，常年作为赛季前期经典分站，车迷氛围浓厚。', '2026-05-09 16:47:08'),
                                                                                         (2, '上海国际赛道', '中国', '5.451km', 56, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Shanghai%20International%20Circuit.jpg', '国内首条顶级F1永久赛道，整体呈现独特上字形布局，拥有标志性连续高速弯与超长直道。赛道缓冲区宽阔安全，兼顾高速冲刺与技术弯角考验，是F1重返中国后的核心举办场地，承载无数经典赛事记忆。', '2026-05-09 16:47:08'),
                                                                                         (3, '铃鹿赛道', '日本', '5.807km', 53, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Suzuka%20International%20Racing%20Course.jpg', '全球唯一八字形交叉布局赛道，被公认为车手最喜爱的赛道之一。130R高速弯、连续S弯极具挑战性，对赛车底盘平衡、走线精度要求极高，天气变化频繁，极易诞生精彩攻防与意外赛果。', '2026-05-09 16:47:08'),
                                                                                         (4, '巴林国际赛道', '巴林', '5.412km', 57, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Bahrain%20International%20Circuit.jpg', '地处萨基尔沙漠的经典沙漠赛道，也是F1最早开启夜赛模式的场地。赛道直道与中高速弯交错，路况稳定，常年作为冬季新车测试地，灯光加持下夜赛观赏性极强，开局阶段战略博弈激烈。', '2026-05-09 16:47:08'),
                                                                                         (5, '吉达滨海赛道', '沙特阿拉伯', '6.174km', 50, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Jeddah%20Corniche%20Circuit.jpg', 'F1赛历中平均车速最快的街道赛道，沿红海海岸线修建，全程多高速连续弯，赛道狭窄缓冲区少。以夜间赛事为主，车速极高、容错率极低，极度考验车手胆量与走线精准度。', '2026-05-09 16:47:08'),
                                                                                         (6, '迈阿密国际赛道', '美国', '5.412km', 57, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Miami%20International%20Autodrome.jpg', '环绕体育场打造的城市临时赛道，美式娱乐氛围拉满。地处热带高温高湿环境，赛道初始抓地力偏低，轮胎损耗严重，车队策略与安全车因素往往左右最终比赛结果。', '2026-05-09 16:47:08'),
                                                                                         (7, '吉尔·维伦纽夫赛道', '加拿大', '4.361km', 70, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Circuit%20Gilles%20Villeneuve.jpg', '位于蒙特利尔圣母岛，以赛道末端著名冠军墙闻名于世。赛道直道长、重刹区域多，对刹车系统损耗极大，路面颠簸多变，稍有失误便容易上墙撞车，赛事变数十足。', '2026-05-09 16:47:08'),
                                                                                         (8, '摩纳哥蒙特卡洛街道赛道', '摩纳哥', '3.337km', 78, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Circuit%20de%20Monaco.jpg', 'F1难度天花板街道赛道，全程依托城市街道修建，几乎无缓冲区。隧道、港口弯、发卡弯极具辨识度，赛道狭窄难以超车，排位赛成绩基本锁定正赛排名，是身份与荣誉的象征之战。', '2026-05-09 16:47:08'),
                                                                                         (9, '加泰罗尼亚赛道', '西班牙巴塞罗那', '4.657km', 66, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Circuit%20de%20Barcelona-Catalunya.jpg', 'F1经典全能型测试赛道，布局均衡，高速弯、低速发卡弯、长直道一应俱全。常年作为冬季新车测试主场，能全面检验赛车空气动力学、底盘调校与轮胎适配能力，比赛节奏稳定。', '2026-05-09 16:47:08'),
                                                                                         (10, '红牛环赛道', '奥地利', '4.318km', 71, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Red%20Bull%20Ring.jpg', '红牛车队主场赛道，坐落于阿尔卑斯山麓，自然风光绝美。赛道弯角少、直道长，整体偏向高速冲刺，尾速表现突出，超车点位清晰，主场车迷氛围热烈，极易上演激烈攻防战。', '2026-05-09 16:47:08'),
                                                                                         (11, '银石赛道', '英国', '5.891km', 52, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Silverstone%20Circuit.jpg', 'F1运动发源地，被誉为赛车摇篮。以Copse、Maggotts、Becketts连续高速弯组合为标志，全程节奏紧凑车速极快，历史底蕴深厚，英国本土车迷氛围堪称围场顶级。', '2026-05-09 16:47:08'),
                                                                                         (12, '斯帕-弗朗科尔尚赛道', '比利时', '7.004km', 44, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Circuit%20de%20Spa-Francorchamps.jpg', 'F1赛历最长赛道，坐落于阿登山区，经典的Eau Rouge弯名扬全球。山区天气阴晴不定，经常一边晴一边雨，赛道起伏大、高速路段多，是所有车手心中的梦幻赛道。', '2026-05-09 16:47:08'),
                                                                                         (13, '亨格罗林赛道', '匈牙利', '4.381km', 70, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Hungaroring.jpg', '有着欧洲摩纳哥之称，赛道多连续低速弯，缺乏长直道，很难实现超车。夏季高温闷热，轮胎衰减极快，极其考验车队战术调校与车手保胎能力，比赛胜负多由策略决定。', '2026-05-09 16:47:08'),
                                                                                         (14, '赞德沃特赛道', '荷兰', '4.259km', 72, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Circuit%20Zandvoort.jpg', '北海沿岸海岸赛道，拥有标志性倾斜 banking 弯角，可支持极高车速全油门通过。作为维斯塔潘主场，全场被橙色车迷海洋包围，氛围狂热，风况多变对赛车空气动力学调校要求严苛。', '2026-05-09 16:47:08'),
                                                                                         (15, '蒙扎赛道', '意大利', '5.793km', 53, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Autodromo%20Nazionale%20Monza.jpg', '素有速度圣殿之称，F1历史最悠久赛道之一。全油门路段占比极高，直道超长尾速冠绝赛历，弯道少且简单。作为法拉利主场，数万tifosi车迷齐聚，氛围狂热，纯粹追求极速比拼。', '2026-05-09 16:47:08'),
                                                                                         (16, '马德里城市赛道', '西班牙马德里', '5.400km', 55, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Madrid%20Circuit.jpg', '全新加入赛历的马德里城市街道赛道，依托城市主干道规划，弯角组合丰富，兼顾高速直道与技术型连续弯。赛道设计现代，观赛区域开阔，为F1西班牙分站全新替代场地，赛事商业氛围浓厚。', '2026-05-09 16:47:08'),
                                                                                         (17, '巴库城市赛道', '阿塞拜疆', '6.003km', 51, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Baku%20City%20Circuit.jpg', '融合超长极速直道与老城狭窄街道的独特赛道，直道尾速可突破360km/h，老城路段弯角密集容错率低。比赛经常出现安全车、虚拟安全车，赛况跌宕起伏，冷门频出。', '2026-05-09 16:47:08'),
                                                                                         (18, '滨海湾街道赛道', '新加坡', '5.063km', 61, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Marina%20Bay%20Street%20Circuit.jpg', '全球首场F1全夜间街道赛，依托滨海湾城市夜景修建，弯角数量多且多为低速连续弯。常年高温高湿闷热，对车手体能、赛车刹车与轮胎耐久都是极大考验，夜景赛事辨识度极高。', '2026-05-09 16:47:08'),
                                                                                         (19, '美洲赛道', '美国奥斯汀', '5.513km', 56, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Circuit%20of%20the%20Americas.jpg', '美式经典F1赛道，标志性上坡连续弯独一无二，布局兼顾高速、技术弯与超车区。赛道视野开阔观赛体验极佳，天气多变，经常上演激烈的车手缠斗与战术博弈。', '2026-05-09 16:47:08'),
                                                                                         (20, '罗德里格斯兄弟赛道', '墨西哥', '4.304km', 71, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Aut%C3%B3dromo%20Hermanos%20Rodr%C3%ADguez.jpg', '海拔超2000米高海拔赛道，空气稀薄动力输出受影响。内置体育场直道区域，车迷聚集氛围炸裂，赛道抓地力特殊，风况复杂，调校与常规赛道差异极大。', '2026-05-09 16:47:08'),
                                                                                         (21, '因特拉戈斯赛道', '巴西', '4.309km', 71, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Aut%C3%B3dromo%20Jos%C3%A9%20Carlos%20Pace.jpg', '南美经典传奇赛道，地形起伏明显，塞纳S弯为标志性路段。常年多雨多阴天，雨战概率极高，赛道抓地力偏低，充满不确定性，历来是诞生逆转与经典收官之战的场地。', '2026-05-09 16:47:08'),
                                                                                         (22, '拉斯维加斯街道赛道', '美国', '6.120km', 50, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Las%20Vegas%20Strip%20Circuit.jpg', '沿拉斯维加斯大道打造的夜间奢华街道赛道，霓虹夜景加持辨识度拉满。长直道车速惊人，弯角设计偏向娱乐观赏性，是F1商业属性最强、关注度最高的分站之一。', '2026-05-09 16:47:08'),
                                                                                         (23, '卢赛尔国际赛道', '卡塔尔', '5.419km', 57, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Lusail%20International%20Circuit.jpg', '中东沙漠夜赛赛道，赛道走线流畅圆润，中高速弯比例高，整体节奏均衡。夜间温度适宜轮胎工作，比赛节奏平稳，赛季末期成为车手抢分、车队布局收官战的关键场地。', '2026-05-09 16:47:08'),
                                                                                         (24, '亚斯码头赛道', '阿联酋阿布扎比', '5.281km', 58, 'https://f1-images-1429537737.cos.ap-beijing.myqcloud.com/track/Yas%20Marina%20Circuit.jpg', 'F1赛季固定收官战场地，赛道包含隧道弯、港口游艇景观，夜赛环境唯美。赛道可调度弯角设计合理，超车机会充足，每年都在这里决出年度车手与车队总冠军，承载无数收官经典时刻。', '2026-05-09 16:47:08');
